BEGIN;
DO $test$
DECLARE ceo uuid:='b8cbf27e-2391-4fb5-b061-f1488e8c3135'; cpo uuid; cmo uuid; cfo uuid; p uuid; plan uuid; planning_job uuid; d uuid; failed uuid; newer uuid; key uuid:=gen_random_uuid(); token uuid:=gen_random_uuid(); turn public.discussion_turns; ids jsonb; revision integer; i integer; w public.tasks; refs jsonb; expected jsonb;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',ceo::text,true);
 SELECT id INTO cpo FROM public.agents WHERE code='CPO';SELECT id INTO cmo FROM public.agents WHERE code='CMO';SELECT id INTO cfo FROM public.agents WHERE code='CFO';
 p:=public.create_company_project('DIALOGUE ROLLBACK FIXTURE','澄清项目业务边界','有明确结论','人工验证全流程','[{"title":"项目交付","acceptance":"检查边界与依据"}]',gen_random_uuid());
 plan:=public.plan_company_project(p,0);
 SELECT (result->>'current_job_id')::uuid INTO planning_job FROM public.tasks WHERE id=plan;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=planning_job;
 PERFORM public.complete_chat_reply(planning_job,token,'Fixture plan','[]');
 PERFORM public.review_work_plan(plan,0,'{"mode":"team","reason":"两步交接","missing_information":[],"tasks":[{"title":"确认依据","agent_code":"CPO","instruction":"核对文本","acceptance":"明确依据","after":[]},{"title":"对外口径","agent_code":"CMO","instruction":"使用前置依据","acceptance":"不虚构","after":[0]}]}',true);
 SELECT jsonb_agg(id) INTO ids FROM public.tasks WHERE task_kind='plan_assignment' AND input->>'plan_id'=plan::text;
 PERFORM public.configure_company_project(p,1,plan,jsonb_build_array(jsonb_build_object('title','项目交付','acceptance','检查边界与依据','task_ids',ids)));
 SELECT cp.revision INTO revision FROM public.company_projects cp WHERE cp.id=p;
 BEGIN PERFORM public.start_project_discussion(p,revision,cpo,cpo,'自问自答',1,gen_random_uuid());RAISE EXCEPTION 'Same participant allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.start_project_discussion(p,revision,cpo,cfo,'无关参与者',1,gen_random_uuid());RAISE EXCEPTION 'Foreign participant allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.start_project_discussion(p,revision-1,cmo,cpo,'旧版本',1,gen_random_uuid());RAISE EXCEPTION 'Stale project allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.start_project_discussion(p,revision,cmo,cpo,'无限轮次',3,gen_random_uuid());RAISE EXCEPTION 'Round bound ignored';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 d:=public.start_project_discussion(p,revision,cmo,cpo,'明确宣传与产品能力边界',2,key);
 IF public.start_project_discussion(p,revision,cmo,cpo,'明确宣传与产品能力边界',2,key)<>d THEN RAISE EXCEPTION 'Duplicate thread';END IF;
 BEGIN PERFORM public.start_project_discussion(p,revision,cmo,cpo,'并发空聊',1,gen_random_uuid());RAISE EXCEPTION 'Active thread limit ignored';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 FOR i IN 1..4 LOOP
  SELECT * INTO turn FROM public.discussion_turns WHERE discussion_id=d ORDER BY round_number DESC,phase DESC LIMIT 1;
  IF turn.phase<>((i-1)%2) OR turn.agent_id<>(CASE WHEN turn.phase=0 THEN cmo ELSE cpo END) THEN RAISE EXCEPTION 'Wrong participant progression';END IF;
  UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=turn.job_id;
  BEGIN PERFORM public.complete_chat_reply(turn.job_id,gen_random_uuid(),'Wrong lease','[]');RAISE EXCEPTION 'Stale lease allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
  PERFORM public.complete_chat_reply(turn.job_id,token,CASE WHEN turn.phase=0 THEN '请说明本次项目边界？' ELSE '这是固定项目版本的建议答复，不等于验收。' END,'[]');
  PERFORM public.complete_chat_reply(turn.job_id,token,'Duplicate callback','[]');
 END LOOP;
 IF (SELECT count(*) FROM public.discussion_turns WHERE discussion_id=d)<>4 OR NOT EXISTS(SELECT 1 FROM public.project_discussions WHERE id=d AND state='completed' AND snapshot->>'goal'='澄清项目业务边界') THEN RAISE EXCEPTION 'Unbounded or unfinished discussion';END IF;
 IF EXISTS(SELECT 1 FROM public.project_checks WHERE project_id=p) OR EXISTS(SELECT 1 FROM public.company_projects WHERE id=p AND state='accepted') THEN RAISE EXCEPTION 'Discussion performed acceptance';END IF;
 SELECT wo.* INTO w FROM public.tasks s JOIN public.tasks wo ON wo.id=(s.result->>'work_order_id')::uuid WHERE s.task_kind='plan_assignment' AND s.input->>'plan_id'=plan::text AND s.assigned_agent_id=cpo;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=(w.result->>'current_job_id')::uuid;
 BEGIN PERFORM public.discussion_context_for_task((w.result->>'current_job_id')::uuid,gen_random_uuid());RAISE EXCEPTION 'Context without lease';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 refs:=public.discussion_context_for_task((w.result->>'current_job_id')::uuid,token);
 IF jsonb_array_length(refs)<>1 OR refs->0->>'discussion_id'<>d::text THEN RAISE EXCEPTION 'Completed discussion not reused';END IF;
 failed:=public.start_project_discussion(p,revision,cmo,cpo,'失败恢复验证',1,gen_random_uuid());
 SELECT * INTO turn FROM public.discussion_turns WHERE discussion_id=failed;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=turn.job_id;
 PERFORM public.fail_chat_reply(turn.job_id,token,'synthetic_fault',false,'[]');PERFORM public.retry_project_discussion(failed);
 IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=turn.job_id AND execution_state='queued' AND attempt_count=1) THEN RAISE EXCEPTION 'Retry history lost';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=2,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=turn.job_id;
 PERFORM public.fail_chat_reply(turn.job_id,token,'synthetic_fault',false,'[]');PERFORM public.close_failed_project_discussion(failed);
 IF NOT EXISTS(SELECT 1 FROM public.project_discussions WHERE id=failed AND state='cancelled') THEN RAISE EXCEPTION 'Failed thread not closed';END IF;
 newer:=public.start_project_discussion(p,revision,cmo,cpo,'新的答复不能改变重试快照',1,gen_random_uuid());
 FOR i IN 1..2 LOOP
  SELECT * INTO turn FROM public.discussion_turns WHERE discussion_id=newer ORDER BY phase DESC LIMIT 1;
  UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=turn.job_id;
  PERFORM public.complete_chat_reply(turn.job_id,token,'新回合合成内容，不改变既有执行快照。','[]');
 END LOOP;
 expected:=public.discussion_context_for_task((w.result->>'current_job_id')::uuid,token);
 IF expected IS DISTINCT FROM refs THEN RAISE EXCEPTION 'Retry changed pinned references';END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.start_project_discussion(p,revision,cmo,cpo,'跨账户',1,gen_random_uuid());RAISE EXCEPTION 'Foreign owner allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.discussion_turns','INSERT') OR has_table_privilege('authenticated','public.project_discussions','UPDATE') OR has_function_privilege('authenticated','public.discussion_context_for_task(uuid,uuid)','EXECUTE') OR has_function_privilege('anon','public.start_project_discussion(uuid,integer,uuid,uuid,text,integer,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Excess collaboration privileges';END IF;
END $test$;
SET LOCAL ROLE authenticated;
DO $rls$ BEGIN IF EXISTS(SELECT 1 FROM public.project_discussions) OR EXISTS(SELECT 1 FROM public.discussion_turns) THEN RAISE EXCEPTION 'Discussion RLS leak';END IF;END $rls$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: project participants, ownership, version checks, idempotency, bounded automatic questions/replies, lease denial, retries, failed closure, no automatic acceptance, pinned task references and RLS; rolled back' AS checks;
